/**
 * Curated, bundled word lists (generated by scripts/build-wordlist.py).
 * Lazily loaded via dynamic import so they become separate chunks, not part of the main bundle.
 *
 * - `common`: everyday words (SCOWL size <= 35, Zipf >= 2.6, plus a small allowlist).
 * - `extended`: less common but still familiar words (SCOWL <= 50). Does NOT include `common`.
 * - `targets`: a stricter subset of `common` (SCOWL <= 35, Zipf >= 3.3) for "headline" words such
 *   as Letter Wheel's full-wheel target. Not part of `loadWords`.
 */
export type WordTier = 'common' | 'extended' | 'targets';

const loaders: Record<WordTier, () => Promise<string>> = {
  common: () => import('./data/common.txt?raw').then((m) => m.default),
  extended: () => import('./data/extended.txt?raw').then((m) => m.default),
  targets: () => import('./data/targets.txt?raw').then((m) => m.default),
};

const cache = new Map<WordTier, Promise<readonly string[]>>();

/** Words of one tier, sorted alphabetically (stable order => seeded picks are reproducible). */
export function loadTier(tier: WordTier): Promise<readonly string[]> {
  let p = cache.get(tier);
  if (!p) {
    p = loaders[tier]().then((t) => t.split('\n').filter(Boolean));
    cache.set(tier, p);
  }
  return p;
}

/**
 * Load words. `tier: 'extended'` returns common + extended (a superset, useful for validating guesses);
 * `'common'` returns only common words (good for choosing answers).
 */
export async function loadWords(
  tier: WordTier = 'common',
  opts: { minLength?: number; maxLength?: number } = {},
): Promise<readonly string[]> {
  const { minLength = 0, maxLength = Infinity } = opts;
  const lists =
    tier === 'common'
      ? [await loadTier('common')]
      : await Promise.all([loadTier('common'), loadTier('extended')]);
  const out = lists.flat().filter((w) => w.length >= minLength && w.length <= maxLength);
  return tier === 'common' ? out : out.sort();
}

/** Group words by length. */
export function byLength(words: readonly string[]): Map<number, string[]> {
  const m = new Map<number, string[]>();
  for (const w of words) {
    const a = m.get(w.length);
    if (a) a.push(w);
    else m.set(w.length, [w]);
  }
  return m;
}
